# ============ writer + self-verify ============
IDS = ["DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007","LR-001",
"LR2-013","LR2-014","LR2-015","LR2-016","LR2-017","LR2-018","LR2-019","LR2-020","LR2-021","LR2-022","LR2-023","LR2-024",
"LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116",
"LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
assert len(IDS) == 40 and set(IDS) == set(DATA.keys()), (len(IDS), set(IDS) ^ set(DATA.keys()))
os.makedirs(BASE, exist_ok=True)
total = 0
for cid in IDS:
    p = os.path.join(BASE, cid + ".json")
    assert not os.path.exists(p), "refuse overwrite: " + p
    s = json.dumps(DATA[cid], ensure_ascii=False, indent=1)
    with open(p, "w", encoding="utf-8") as f:
        f.write(s + "\n")
    total += os.path.getsize(p)
# verify each file exactly
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    p = os.path.join(BASE, cid + ".json")
    with open(p, encoding="utf-8") as f:
        d = json.load(f)
    assert set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert d["case_id"] == cid
    assert isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1, cid
    t = d["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
    for k in ("changed_main","reserve_used","disputed"):
        assert isinstance(t[k], bool), cid
        if t[k]: trig[k] += 1
    assert isinstance(t["reason"], str)
print("WROTE", len(IDS), "TOTAL_BYTES", total, "TRIGGER", trig)
